class Policy:
    # Track scores and prioritize unsolved tasks, falling back to round-robin among unknowns.
    def __init__(self):
        self.scores = {}
        self.attempts = {}

    def pick(self, keys, round_index):
        # First, prefer tasks we haven't tried yet (unknown difficulty)
        untried = [k for k in keys if k not in self.scores]
        if untried:
            # Among untried, use round-robin to spread exploration
            return untried[round_index % len(untried)]

        # All tried: pick the one with lowest score (most likely to improve)
        # Among ties, prefer least attempted
        def sort_key(k):
            return (self.scores.get(k, 0), self.attempts.get(k, 0))
        return min(keys, key=sort_key)

    def record(self, task_id, score):
        self.scores[task_id] = score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
```

